INSERT INTO public.ano_biblico_textos (livro_abrev, capitulo, idioma, versiculos, fonte)
VALUES
  ('Sl', 148, 'pt', '[{"numero": 1, "texto": "Aleluia! Louvai ao SENHOR desde os céus; louvai-o nas alturas."}, {"numero": 2, "texto": "Louvai-o todos os seus anjos; louvai-o todos os seus exércitos."}, {"numero": 3, "texto": "Louvai-o, sol e lua; louvai-o, todas as estrelas luminosas."}, {"numero": 4, "texto": "Louvai-o, céus dos céus, e as águas que [estais] sobre os céus."}, {"numero": 5, "texto": "Louvem ao nome do SENHOR; porque pela ordem dele foram criados."}, {"numero": 6, "texto": "E os firmou para todo o sempre; e deu [tal] decreto, que não será traspassado."}, {"numero": 7, "texto": "Louvai ao SENHOR [vós] da terra: os monstros marinhos, e todos os abismos;"}, {"numero": 8, "texto": "O fogo e a saraiva, a neve e o vapor; o vento tempestuoso, que executa sua palavra."}, {"numero": 9, "texto": "Os montes e todos os morros; árvores frutíferas, e todos os cedros."}, {"numero": 10, "texto": "As feras, e todo o gado; répteis, e aves que tem asas."}, {"numero": 11, "texto": "Os reis da terra, e todos os povos; os príncipes, e todos os juízes da terra."}, {"numero": 12, "texto": "Os rapazes, e também as moças; os velhos com os jovens."}, {"numero": 13, "texto": "Louvem ao nome do SENHOR; pois só o nome dele é exaltado; sua majestade [está] sobre a terra e o céu."}, {"numero": 14, "texto": "E ele exaltou o poder de seu povo: o louvor de todos os seus santos, os filhos de Israel, o povo [que está] perto dele. Aleluia!"}]'::jsonb, 'Almeida Livre'),
  ('Sl', 148, 'en', '[{"numero": 1, "texto": "Praise ye the Lord. Praise ye the Lord from the heavens: praise him in the heights."}, {"numero": 2, "texto": "Praise ye him, all his angels: praise ye him, all his hosts."}, {"numero": 3, "texto": "Praise ye him, sun and moon: praise him, all ye stars of light."}, {"numero": 4, "texto": "Praise him, ye heavens of heavens, and ye waters that be above the heavens."}, {"numero": 5, "texto": "Let them praise the name of the Lord: for he commanded, and they were created."}, {"numero": 6, "texto": "He hath also stablished them for ever and ever: he hath made a decree which shall not pass."}, {"numero": 7, "texto": "Praise the Lord from the earth, ye dragons, and all deeps:"}, {"numero": 8, "texto": "Fire, and hail; snow, and vapours; stormy wind fulfilling his word:"}, {"numero": 9, "texto": "Mountains, and all hills; fruitful trees, and all cedars:"}, {"numero": 10, "texto": "Beasts, and all cattle; creeping things, and flying fowl:"}, {"numero": 11, "texto": "Kings of the earth, and all people; princes, and all judges of the earth:"}, {"numero": 12, "texto": "Both young men, and maidens; old men, and children:"}, {"numero": 13, "texto": "Let them praise the name of the Lord: for his name alone is excellent; his glory is above the earth and heaven."}, {"numero": 14, "texto": "He also exalteth the horn of his people, the praise of all his saints; even of the children of Israel, a people near unto him. Praise ye the Lord."}]'::jsonb, 'King James Version'),
  ('Sl', 148, 'fr', '[{"numero": 1, "texto": "Louez l''''Eternel! Louez l''''Eternel du haut des cieux! Louez-le dans les lieux élevés!"}, {"numero": 2, "texto": "Louez-le, vous tous ses anges! Louez-le, vous toutes ses armées!"}, {"numero": 3, "texto": "Louez-le, soleil et lune! Louez-le, vous toutes, étoiles lumineuses!"}, {"numero": 4, "texto": "Louez-le, cieux des cieux, Et vous, eaux qui êtes au-dessus des cieux!"}, {"numero": 5, "texto": "Qu''''ils louent le nom de l''''Eternel! Car il a commandé, et ils ont été créés."}, {"numero": 6, "texto": "Il les a affermis pour toujours et à perpétuité; Il a donné des lois, et il ne les violera point."}, {"numero": 7, "texto": "Louez l''''Eternel du bas de la terre, Monstres marins, et vous tous, abîmes,"}, {"numero": 8, "texto": "Feu et grêle, neige et brouillards, Vents impétueux, qui exécutez ses ordres,"}, {"numero": 9, "texto": "Montagnes et toutes les collines, Arbres fruitiers et tous les cèdres,"}, {"numero": 10, "texto": "Animaux et tout le bétail, Reptiles et oiseaux ailés,"}, {"numero": 11, "texto": "Rois de la terre et tous les peuples, Princes et tous les juges de la terre,"}, {"numero": 12, "texto": "Jeunes hommes et jeunes filles, Vieillards et enfants!"}, {"numero": 13, "texto": "Qu''''ils louent le nom de l''''Eternel! Car son nom seul est élevé; Sa majesté est au-dessus de la terre et des cieux."}, {"numero": 14, "texto": "Il a relevé la force de son peuple: Sujet de louange pour tous ses fidèles, Pour les enfants d''''Israël, du peuple qui est près de lui. Louez l''''Eternel!"}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 148, 'es', '[{"numero": 1, "texto": "ALABAD á Jehová desde los cielos: alabadle en las alturas."}, {"numero": 2, "texto": "Alabadle, vosotros todos sus ángeles: alabadle, vosotros todos sus ejércitos."}, {"numero": 3, "texto": "Alabadle, sol y luna: alabadle, vosotras todas, lucientes estrellas."}, {"numero": 4, "texto": "Alabadle, cielos de los cielos, y las aguas que están sobre los cielos."}, {"numero": 5, "texto": "Alaben el nombre de Jehová; porque él mandó, y fueron criadas."}, {"numero": 6, "texto": "Y las hizo ser para siempre por los siglos; púsoles ley que no será quebrantada."}, {"numero": 7, "texto": "Alabad á Jehová, de la tierra los dragones y todos los abismos;"}, {"numero": 8, "texto": "El fuego y el granizo, la nieve y el vapor, el viento de tempestad que ejecuta su palabra;"}, {"numero": 9, "texto": "Los montes y todos los collados; el árbol de fruto, y todos los cedros;"}, {"numero": 10, "texto": "La bestia y todo animal; reptiles y volátiles;"}, {"numero": 11, "texto": "Los reyes de la tierra y todos los pueblos; los príncipes y todos los jueces de la tierra;"}, {"numero": 12, "texto": "Los mancebos y también las doncellas; los viejos y los niños,"}, {"numero": 13, "texto": "Alaben el nombre de Jehová, porque sólo su nombre es elevado; su gloria es sobre tierra y cielos."}, {"numero": 14, "texto": "El ensalzó el cuerno de su pueblo; alábenle todos sus santos, los hijos de Israel, el pueblo á él cercano. Aleluya."}]'::jsonb, 'Reina-Valera 1909'),
  ('Tg', 1, 'pt', '[{"numero": 1, "texto": "Tiago, servo de Deus e do Senhor Jesus Cristo, às doze tribos que [estão] na dispersão, saudações!"}, {"numero": 2, "texto": "Meus irmãos, tende toda alegria quando vos encontrardes em várias provações,"}, {"numero": 3, "texto": "sabendo que a prova da vossa fé produz perseverança."}, {"numero": 4, "texto": "E que a perseverança tenha uma realização completa, para que sejais completos e íntegros, faltando em nada."}, {"numero": 5, "texto": "Se algum de vós tem falta de sabedoria, peça a Deus, que concede generosamente a todos sem repreender, e lhe será dada."}, {"numero": 6, "texto": "Porém deves pedi-la em fé, duvidando em nada; pois quem duvida é semelhante à onda do mar que é levada pelo vento, e lançada."}, {"numero": 7, "texto": "Tal pessoa não pense que receberá algo do Senhor."}, {"numero": 8, "texto": "O homem de dupla mentalidade [é] inconstante em todos os seus caminhos."}, {"numero": 9, "texto": "Mas o irmão que é humilde se orgulhe quando é exaltado,"}, {"numero": 10, "texto": "e o que é rico quando é abatido, porque ele passará como a flor da erva."}, {"numero": 11, "texto": "Pois o sol sai com ardor, então seca a erva, a sua flor cai, e a beleza do seu aspecto perece; assim também o rico murchará nos seus caminhos."}, {"numero": 12, "texto": "Bendito é o homem que suporta a provação; pois, quando for aprovado, receberá a coroa da vida, que o Senhor prometeu aos que o amam."}, {"numero": 13, "texto": "Ninguém, quando for tentado, diga: “Sou tentado por Deus”; porque Deus não é tentado pelo mal, e ele mesmo tenta ninguém;"}, {"numero": 14, "texto": "Mas cada um é tentado quando é atraído e seduzido pelo seu próprio mau desejo."}, {"numero": 15, "texto": "Depois do mau desejo ter concebido, dá à luz o pecado; e o pecado, quando é completado, gera a morte."}, {"numero": 16, "texto": "Não vos enganeis, meus amados irmãos."}, {"numero": 17, "texto": "Toda boa dádiva e todo dom perfeito vem do alto, e desce do Pai das luzes, em quem não há mudança nem sombra de variação."}, {"numero": 18, "texto": "Conforme a sua própria vontade, ele nos gerou pela palavra da verdade, para que fôssemos os primeiros frutos dentre as suas criaturas."}, {"numero": 19, "texto": "Portanto, meus amados irmãos, toda pessoa seja pronta para ouvir, tardia para falar, tardia para se irar;"}, {"numero": 20, "texto": "porque a ira humana não cumpre a justiça de Deus."}, {"numero": 21, "texto": "Por isso, rejeitai toda impureza e abundância de malícia, e recebei com mansidão a palavra implantada em [vós] , que pode salvar as vossas almas;"}, {"numero": 22, "texto": "e sede praticantes da palavra, e não somente ouvintes, enganando a vós mesmos."}, {"numero": 23, "texto": "Pois, se alguém é ouvinte da palavra e não praticante, esse é semelhante a um homem que observa num espelho o seu rosto natural;"}, {"numero": 24, "texto": "porque observou a si mesmo e saiu, e logo se esqueceu de como era."}, {"numero": 25, "texto": "Mas aquele que dá atenção à lei perfeita, a da liberdade, e [nela] persevera, não sendo ouvinte que esquece, mas sim praticante da obra, esse tal será bendito no que fizer."}, {"numero": 26, "texto": "Se alguém entre vós pensa ser religioso, mas não controla a sua língua, então engana o seu próprio coração, e a religião desse é vã."}, {"numero": 27, "texto": "A religião pura e não contaminada para com Deus e Pai é esta: visitar os órfãos e as viúvas nas suas aflições, e guardar-se sem a corrupção do mundo."}]'::jsonb, 'Almeida Livre'),
  ('Tg', 1, 'en', '[{"numero": 1, "texto": "James, a servant of God and of the Lord Jesus Christ, to the twelve tribes which are scattered abroad, greeting."}, {"numero": 2, "texto": "My brethren, count it all joy when ye fall into divers temptations;"}, {"numero": 3, "texto": "Knowing this, that the trying of your faith worketh patience."}, {"numero": 4, "texto": "But let patience have her perfect work, that ye may be perfect and entire, wanting nothing."}, {"numero": 5, "texto": "If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him."}, {"numero": 6, "texto": "But let him ask in faith, nothing wavering. For he that wavereth is like a wave of the sea driven with the wind and tossed."}, {"numero": 7, "texto": "For let not that man think that he shall receive any thing of the Lord."}, {"numero": 8, "texto": "A double minded man is unstable in all his ways."}, {"numero": 9, "texto": "Let the brother of low degree rejoice in that he is exalted:"}, {"numero": 10, "texto": "But the rich, in that he is made low: because as the flower of the grass he shall pass away."}, {"numero": 11, "texto": "For the sun is no sooner risen with a burning heat, but it withereth the grass, and the flower thereof falleth, and the grace of the fashion of it perisheth: so also shall the rich man fade away in his ways."}, {"numero": 12, "texto": "Blessed is the man that endureth temptation: for when he is tried, he shall receive the crown of life, which the Lord hath promised to them that love him."}, {"numero": 13, "texto": "Let no man say when he is tempted, I am tempted of God: for God cannot be tempted with evil, neither tempteth he any man:"}, {"numero": 14, "texto": "But every man is tempted, when he is drawn away of his own lust, and enticed."}, {"numero": 15, "texto": "Then when lust hath conceived, it bringeth forth sin: and sin, when it is finished, bringeth forth death."}, {"numero": 16, "texto": "Do not err, my beloved brethren."}, {"numero": 17, "texto": "Every good gift and every perfect gift is from above, and cometh down from the Father of lights, with whom is no variableness, neither shadow of turning."}, {"numero": 18, "texto": "Of his own will begat he us with the word of truth, that we should be a kind of firstfruits of his creatures."}, {"numero": 19, "texto": "Wherefore, my beloved brethren, let every man be swift to hear, slow to speak, slow to wrath:"}, {"numero": 20, "texto": "For the wrath of man worketh not the righteousness of God."}, {"numero": 21, "texto": "Wherefore lay apart all filthiness and superfluity of naughtiness, and receive with meekness the engrafted word, which is able to save your souls."}, {"numero": 22, "texto": "But be ye doers of the word, and not hearers only, deceiving your own selves."}, {"numero": 23, "texto": "For if any be a hearer of the word, and not a doer, he is like unto a man beholding his natural face in a glass:"}, {"numero": 24, "texto": "For he beholdeth himself, and goeth his way, and straightway forgetteth what manner of man he was."}, {"numero": 25, "texto": "But whoso looketh into the perfect law of liberty, and continueth therein, he being not a forgetful hearer, but a doer of the work, this man shall be blessed in his deed."}, {"numero": 26, "texto": "If any man among you seem to be religious, and bridleth not his tongue, but deceiveth his own heart, this man''s religion is vain."}, {"numero": 27, "texto": "Pure religion and undefiled before God and the Father is this, To visit the fatherless and widows in their affliction, and to keep himself unspotted from the world."}]'::jsonb, 'King James Version'),
  ('Tg', 1, 'fr', '[{"numero": 1, "texto": "Jacques, serviteur de Dieu et du Seigneur Jésus-Christ, aux douze tribus qui sont dans la dispersion, salut!"}, {"numero": 2, "texto": "Mes frères, regardez comme un sujet de joie complète les diverses épreuves auxquelles vous pouvez être exposés,"}, {"numero": 3, "texto": "sachant que l''''épreuve de votre foi produit la patience."}, {"numero": 4, "texto": "Mais il faut que la patience accomplisse parfaitement son oeuvre, afin que vous soyez parfaits et accomplis, sans faillir en rien."}, {"numero": 5, "texto": "Si quelqu''''un d''''entre vous manque de sagesse, qu''''il la demande à Dieu, qui donne à tous simplement et sans reproche, et elle lui sera donnée."}, {"numero": 6, "texto": "Mais qu''''il la demande avec foi, sans douter; car celui qui doute est semblable au flot de la mer, agité par le vent et poussé de côté et d''''autre."}, {"numero": 7, "texto": "Qu''''un tel homme ne s''''imagine pas qu''''il recevra quelque chose du Seigneur:"}, {"numero": 8, "texto": "c''''est un homme irrésolu, inconstant dans toutes ses voies."}, {"numero": 9, "texto": "Que le frère de condition humble se glorifie de son élévation."}, {"numero": 10, "texto": "Que le riche, au contraire, se glorifie de son humiliation; car il passera comme la fleur de l''''herbe."}, {"numero": 11, "texto": "Le soleil s''''est levé avec sa chaleur ardente, il a desséché l''''herbe, sa fleur est tombée, et la beauté de son aspect a disparu: ainsi le riche se flétrira dans ses entreprises."}, {"numero": 12, "texto": "Heureux l''''homme qui supporte patiemment la tentation; car, après avoir été éprouvé, il recevra la couronne de vie, que le Seigneur a promise à ceux qui l''''aiment."}, {"numero": 13, "texto": "Que personne, lorsqu''''il est tenté, ne dise: C''''est Dieu qui me tente. Car Dieu ne peut être tenté par le mal, et il ne tente lui-même personne."}, {"numero": 14, "texto": "Mais chacun est tenté quand il est attiré et amorcé par sa propre convoitise."}, {"numero": 15, "texto": "Puis la convoitise, lorsqu''''elle a conçu, enfante le péché; et le péché, étant consommé, produit la mort."}, {"numero": 16, "texto": "Ne vous y trompez pas, mes frères bien-aimés:"}, {"numero": 17, "texto": "toute grâce excellente et tout don parfait descendent d''''en haut, du Père des lumières, chez lequel il n''''y a ni changement ni ombre de variation."}, {"numero": 18, "texto": "Il nous a engendrés selon sa volonté, par la parole de vérité, afin que nous soyons en quelque sorte les prémices de ses créatures."}, {"numero": 19, "texto": "Sachez-le, mes frères bien-aimés. Ainsi, que tout homme soit prompt à écouter, lent à parler, lent à se mettre en colère;"}, {"numero": 20, "texto": "car la colère de l''''homme n''''accomplit pas la justice de Dieu."}, {"numero": 21, "texto": "C''''est pourquoi, rejetant toute souillure et tout excès de malice, recevez avec douceur la parole qui a été plantée en vous, et qui peut sauver vos âmes."}, {"numero": 22, "texto": "Mettez en pratique la parole, et ne vous bornez pas à l''''écouter, en vous trompant vous-mêmes par de faux raisonnements."}, {"numero": 23, "texto": "Car, si quelqu''''un écoute la parole et ne la met pas en pratique, il est semblable à un homme qui regarde dans un miroir son visage naturel,"}, {"numero": 24, "texto": "et qui, après s''''être regardé, s''''en va, et oublie aussitôt quel il était."}, {"numero": 25, "texto": "Mais celui qui aura plongé les regards dans la loi parfaite, la loi de la liberté, et qui aura persévéré, n''''étant pas un auditeur oublieux, mais se mettant à l''''oeuvre, celui-là sera heureux dans son activité."}, {"numero": 26, "texto": "Si quelqu''''un croit être religieux, sans tenir sa langue en bride, mais en trompant son coeur, la religion de cet homme est vaine."}, {"numero": 27, "texto": "La religion pure et sans tache, devant Dieu notre Père, consiste à visiter les orphelins et les veuves dans leurs afflictions, et à se préserver des souillures du monde."}]'::jsonb, 'Louis Segond 1910'),
  ('Tg', 1, 'es', '[{"numero": 1, "texto": "JACOBO, siervo de Dios y del Señor Jesucristo, á las doce tribus que están esparcidas, salud."}, {"numero": 2, "texto": "Hermanos míos, tened por sumo gozo cuando cayereis en diversas tentaciones;"}, {"numero": 3, "texto": "Sabiendo que la prueba de vuestra fe obra paciencia."}, {"numero": 4, "texto": "Mas tenga la paciencia perfecta su obra, para que seáis perfectos y cabales, sin faltar en alguna cosa."}, {"numero": 5, "texto": "Y si alguno de vosotros tiene falta de sabiduría, demándela á Dios, el cual da á todos abundantemente, y no zahiere; y le será dada."}, {"numero": 6, "texto": "Pero pida en fe, no dudando nada: porque el que duda es semejante á la onda de la mar, que es movida del viento, y echada de una parte á otra."}, {"numero": 7, "texto": "No piense pues el tal hombre que recibirá ninguna cosa del Señor."}, {"numero": 8, "texto": "El hombre de doblado ánimo es inconstante en todos sus caminos."}, {"numero": 9, "texto": "El hermano que es de baja suerte, gloríese en su alteza:"}, {"numero": 10, "texto": "Mas el que es rico, en su bajeza; porque él se pasará como la flor de la hierba."}, {"numero": 11, "texto": "Porque salido el sol con ardor, la hierba se secó, y su flor se cayó, y pereció su hermosa apariencia: así también se marchitará el rico en todos sus caminos."}, {"numero": 12, "texto": "Bienaventurado el varón que sufre la tentación; porque cuando fuere probado, recibirá la corona de vida, que Dios ha prometido á los que le aman."}, {"numero": 13, "texto": "Cuando alguno es tentado, no diga que es tentado de Dios: porque Dios no puede ser tentado de los malos, ni él tienta á alguno:"}, {"numero": 14, "texto": "Sino que cada uno es tentado, cuando de su propia concupiscencia es atraído, y cebado."}, {"numero": 15, "texto": "Y la concupiscencia, después que ha concebido, pare el pecado: y el pecado, siendo cumplido, engendra muerte."}, {"numero": 16, "texto": "Amados hermanos míos, no erréis."}, {"numero": 17, "texto": "Toda buena dádiva y todo don perfecto es de lo alto, que desciende del Padre de las luces, en el cual no hay mudanza, ni sombra de variación."}, {"numero": 18, "texto": "El, de su voluntad nos ha engendrado por la palabra de verdad, para que seamos primicias de sus criaturas."}, {"numero": 19, "texto": "Por esto, mis amados hermanos, todo hombre sea pronto para oir, tardío para hablar, tardío para airarse:"}, {"numero": 20, "texto": "Porque la ira del hombre no obra la justicia de Dios."}, {"numero": 21, "texto": "Por lo cual, dejando toda inmundicia y superfluidad de malicia, recibid con mansedumbre la palabra ingerida, la cual puede hacer salvas vuestras almas."}, {"numero": 22, "texto": "Mas sed hacedores de la palabra, y no tan solamente oidores, engañándoos á vosotros mismos."}, {"numero": 23, "texto": "Porque si alguno oye la palabra, y no la pone por obra, este tal es semejante al hombre que considera en un espejo su rostro natural."}, {"numero": 24, "texto": "Porque él se consideró á sí mismo, y se fué, y luego se olvidó qué tal era."}, {"numero": 25, "texto": "Mas el que hubiere mirado atentamente en la perfecta ley, que es la de la libertad, y perseverado en ella, no siendo oidor olvidadizo, sino hacedor de la obra, este tal será bienaventurado en su hecho."}, {"numero": 26, "texto": "Si alguno piensa ser religioso entre vosotros, y no refrena su lengua, sino engañando su corazón, la religión del tal es vana."}, {"numero": 27, "texto": "La religión pura y sin mácula delante de Dios y Padre es esta: Visitar los huérfanos y las viudas en sus tribulaciones, y guardarse sin mancha de este mundo."}]'::jsonb, 'Reina-Valera 1909'),
  ('Zc', 4, 'pt', '[{"numero": 1, "texto": "E o anjo que falava comigo voltou e me despertou, tal como se desperta um homem de seu sono."}, {"numero": 2, "texto": "E ele me disse: O que vês? E eu respondi: Eis que vejo um castiçal de ouro maciço, com um recipiente de azeite sobre seu topo, e sete lâmpadas sobre ele; e cada uma das sete lâmpadas tinha um tubo em seu topo;"}, {"numero": 3, "texto": "E duas oliveiras junto a ele, uma à direita do recipiente, e uma à esquerda."}, {"numero": 4, "texto": "E eu perguntei ao anjo que falava comigo, dizendo: Meu senhor, o que é isto?"}, {"numero": 5, "texto": "E o anjo que falava comigo respondeu dizendo: Tu não sabes que é isto? E eu disse: Não, meu senhor."}, {"numero": 6, "texto": "E ele falou comigo, dizendo: Esta é palavra do SENHOR a Zorobabel, que diz: Não [se fará] por força, nem por violência, mas sim por meu espírito, diz o SENHOR dos exércitos."}, {"numero": 7, "texto": "Quem és tu, montanha grande? Diante de Zorobabel se tornarás em planície; ele trará a pedra angular com gritos de: Graça! graça seja!"}, {"numero": 8, "texto": "E palavra do SENHOR veio a mim, dizendo:"}, {"numero": 9, "texto": "As mãos de Zorobabel fundaram esta casa; também suas mãos a completarão, para que saibais que o SENHOR dos exércitos me enviou até vós."}, {"numero": 10, "texto": "Pois quem despreza o dia das pequenas coisas? Pois esses sete se alegrarão ao verem o prumo na mão de Zorobabel (esses são os olhos do SENHOR, que percorrem toda a terra)."}, {"numero": 11, "texto": "E eu respondi, perguntando: O que são as duas oliveiras à direita e à esquerda do castiçal?"}, {"numero": 12, "texto": "E também lhe perguntei: O que são aqueles dois ramos de oliveiras que estão de lado dos dois tubos de ouro que derramam [azeite] dourado?"}, {"numero": 13, "texto": "E ele falou comigo, dizendo: Tu não sabes o que é isto? E eu disse: Não, meu senhor."}, {"numero": 14, "texto": "Então ele disse: Estes são os dois ungidos que estão diante do Senhor de toda a terra."}]'::jsonb, 'Almeida Livre'),
  ('Zc', 4, 'en', '[{"numero": 1, "texto": "And the angel that talked with me came again, and waked me, as a man that is wakened out of his sleep."}, {"numero": 2, "texto": "And said unto me, What seest thou? And I said, I have looked, and behold a candlestick all of gold, with a bowl upon the top of it, and his seven lamps thereon, and seven pipes to the seven lamps, which are upon the top thereof:"}, {"numero": 3, "texto": "And two olive trees by it, one upon the right side of the bowl, and the other upon the left side thereof."}, {"numero": 4, "texto": "So I answered and spake to the angel that talked with me, saying, What are these, my lord?"}, {"numero": 5, "texto": "Then the angel that talked with me answered and said unto me, Knowest thou not what these be? And I said, No, my lord."}, {"numero": 6, "texto": "Then he answered and spake unto me, saying, This is the word of the Lord unto Zerubbabel, saying, Not by might, nor by power, but by my spirit, saith the Lord of hosts."}, {"numero": 7, "texto": "Who art thou, O great mountain? before Zerubbabel thou shalt become a plain: and he shall bring forth the headstone thereof with shoutings, crying, Grace, grace unto it."}, {"numero": 8, "texto": "Moreover the word of the Lord came unto me, saying,"}, {"numero": 9, "texto": "The hands of Zerubbabel have laid the foundation of this house; his hands shall also finish it; and thou shalt know that the Lord of hosts hath sent me unto you."}, {"numero": 10, "texto": "For who hath despised the day of small things? for they shall rejoice, and shall see the plummet in the hand of Zerubbabel with those seven; they are the eyes of the Lord, which run to and fro through the whole earth."}, {"numero": 11, "texto": "Then answered I, and said unto him, What are these two olive trees upon the right side of the candlestick and upon the left side thereof?"}, {"numero": 12, "texto": "And I answered again, and said unto him, What be these two olive branches which through the two golden pipes empty the golden oil out of themselves?"}, {"numero": 13, "texto": "And he answered me and said, Knowest thou not what these be? And I said, No, my lord."}, {"numero": 14, "texto": "Then said he, These are the two anointed ones, that stand by the Lord of the whole earth."}]'::jsonb, 'King James Version'),
  ('Zc', 4, 'fr', '[{"numero": 1, "texto": "L''''ange qui parlait avec moi revint, et il me réveilla comme un homme que l''''on réveille de son sommeil."}, {"numero": 2, "texto": "Il me dit: Que vois-tu? Je répondis: Je regarde, et voici, il y a un chandelier tout d''''or, surmonté d''''un vase et portant sept lampes, avec sept conduits pour les lampes qui sont au sommet du chandelier;"}, {"numero": 3, "texto": "et il y a près de lui deux oliviers, l''''un à la droite du vase, et l''''autre à sa gauche."}, {"numero": 4, "texto": "Et reprenant la parole, je dis à l''''ange qui parlait avec moi: Que signifient ces choses, mon seigneur?"}, {"numero": 5, "texto": "L''''ange qui parlait avec moi me répondit: Ne sais-tu pas ce que signifient ces choses? Je dis: Non, mon seigneur."}, {"numero": 6, "texto": "Alors il reprit et me dit: C''''est ici la parole que l''''Eternel adresse à Zorobabel: Ce n''''est ni par la puissance ni par la force, mais c''''est par mon esprit, dit l''''Eternel des armées."}, {"numero": 7, "texto": "Qui es-tu, grande montagne, devant Zorobabel? Tu seras aplanie. Il posera la pierre principale au milieu des acclamations: Grâce, grâce pour elle!"}, {"numero": 8, "texto": "La parole de l''''Eternel me fut adressée, en ces mots:"}, {"numero": 9, "texto": "Les mains de Zorobabel ont fondé cette maison, et ses mains l''''achèveront; et tu sauras que l''''Eternel des armées m''''a envoyé vers vous."}, {"numero": 10, "texto": "Car ceux qui méprisaient le jour des faibles commencements se réjouiront en voyant le niveau dans la main de Zorobabel. Ces sept sont les yeux de l''''Eternel, qui parcourent toute la terre."}, {"numero": 11, "texto": "Je pris la parole et je lui dis: Que signifient ces deux oliviers, à la droite du chandelier et à sa gauche?"}, {"numero": 12, "texto": "Je pris une seconde fois la parole, et je lui dis: Que signifient les deux rameaux d''''olivier, qui sont près des deux conduits d''''or d''''où découle l''''or?"}, {"numero": 13, "texto": "Il me répondit: Ne sais-tu pas ce qu''''ils signifient? Je dis: Non, mon seigneur."}, {"numero": 14, "texto": "Et il dit: Ce sont les deux oints qui se tiennent devant le Seigneur de toute la terre."}]'::jsonb, 'Louis Segond 1910'),
  ('Zc', 4, 'es', '[{"numero": 1, "texto": "Y VOLVIÓ el ángel que hablaba conmigo, y despertóme como un hombre que es despertado de su sueño."}, {"numero": 2, "texto": "Y díjome: ¿Qué ves? Y respondí: He mirado, y he aquí un candelero todo de oro, con su vaso sobre su cabeza, y sus siete lámparas encima del candelero; y siete canales para las lámparas que están encima de él;"}, {"numero": 3, "texto": "Y sobre él dos olivas, la una á la derecha del vaso, y la otra á su izquierda."}, {"numero": 4, "texto": "Proseguí, y hablé á aquel ángel que hablaba conmigo, diciendo: ¿Qué es esto, señor mío?"}, {"numero": 5, "texto": "Y el ángel que hablaba conmigo respondió, y díjome: ¿No sabes qué es esto? Y dije: No, señor mío."}, {"numero": 6, "texto": "Entonces respondió y hablóme, diciendo: Esta es palabra de Jehová á Zorobabel, en que se dice: No con ejército, ni con fuerza, sino con mi espíritu, ha dicho Jehová de los ejércitos."}, {"numero": 7, "texto": "¿Quién eres tú, oh gran monte? Delante de Zorobabel serás reducido á llanura: él sacará la primera piedra con aclamaciones de Gracia, gracia á ella."}, {"numero": 8, "texto": "Y fué palabra de Jehová á mí, diciendo:"}, {"numero": 9, "texto": "Las manos de Zorobabel echarán el fundamento á esta casa, y sus manos la acabarán; y conocerás que Jehová de los ejércitos me envió á vosotros."}, {"numero": 10, "texto": "Porque los que menospreciaron el día de las pequeñeces se alegrarán, y verán la plomada en la mano de Zorobabel. Aquellas siete son los ojos de Jehová que recorren por toda la tierra."}, {"numero": 11, "texto": "Hablé más, y díjele: ¿Qué significan estas dos olivas á la derecha del candelero, y á su izquierda?"}, {"numero": 12, "texto": "Hablé aún de nuevo, y díjele: ¿Qué significan las dos ramas de olivas que por medio de dos tubos de oro vierten de sí aceite como oro?"}, {"numero": 13, "texto": "Y respondióme, diciendo: ¿No sabes qué es esto? Y dije: Señor mío, no."}, {"numero": 14, "texto": "Y él dijo: Estos dos hijos de aceite son los que están delante del Señor de toda la tierra."}]'::jsonb, 'Reina-Valera 1909')
